<script>
import {post} from '../api'
import {signIn} from '../session'
export default {data:()=>({firstName:'',lastName:'',email:'',password:'',confirmPassword:'',busy:false,error:'',message:''}),computed:{register(){return this.$route.path==='/registro'},valid(){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.email)&&this.password.length>0&&(!this.register||(this.firstName.trim()&&this.lastName.trim()&&this.password.length>=8&&this.password===this.confirmPassword))}},methods:{async submit(){if(!this.valid)return;this.busy=true;this.error='';try{if(this.register){await post('/auth/register',{firstName:this.firstName,lastName:this.lastName,email:this.email,password:this.password,confirmPassword:this.confirmPassword});this.password='';this.confirmPassword='';this.message='Tu cuenta fue creada correctamente. Ya puedes iniciar sesión.'}else{signIn(await post('/auth/login',{email:this.email,password:this.password}));this.password='';const next=this.$route.query.next;this.$router.push(typeof next==='string'&&next.startsWith('/')&&!next.startsWith('//')?next:'/perfil')}}catch(e){this.error=e.message}finally{this.busy=false}}}}
</script>
<template><q-page class="auth-page"><aside class="auth-aside"><div class="eyebrow">EVENTOS PERÚ IA</div><h1>Los mejores planes<br>empiezan contigo.</h1><p>Una cuenta para descubrir experiencias<br>y conectar con tu comunidad.</p><span class="auth-flower" aria-hidden="true">✳</span></aside><section class="auth-content"><div class="eyebrow">BIENVENIDO A TU PRÓXIMO PLAN</div><h2>{{register?'Crea tu cuenta':'Qué bueno verte'}}</h2><p>{{register?'Completa tus datos para empezar.':'Ingresa con tu correo y contraseña.'}}</p><q-banner v-if="error" class="error" role="alert">{{error}}</q-banner><q-banner v-if="message" class="success" role="status">{{message}} <router-link to="/login">Iniciar sesión</router-link></q-banner><q-form @submit="submit" class="form-stack"><template v-if="register"><q-input outlined v-model="firstName" label="Nombres" maxlength="100" autocomplete="given-name"/><q-input outlined v-model="lastName" label="Apellidos" maxlength="100" autocomplete="family-name"/></template><q-input outlined v-model="email" type="email" label="Correo electrónico" autocomplete="email" maxlength="254"/><q-input outlined v-model="password" type="password" label="Contraseña" :hint="register?'Mínimo 8 caracteres':undefined" :autocomplete="register?'new-password':'current-password'" maxlength="128"/><q-input v-if="register" outlined v-model="confirmPassword" type="password" label="Confirmar contraseña" autocomplete="new-password"/><q-btn type="submit" unelevated color="primary" no-caps :label="register?'Crear cuenta':'Iniciar sesión'" :disable="!valid" :loading="busy"/></q-form><p>{{register?'¿Ya tienes una cuenta?':'¿Todavía no tienes cuenta?'}} <router-link :to="register?'/login':'/registro'">{{register?'Inicia sesión':'Regístrate'}}</router-link></p><p class="muted">Google y recuperación por correo están pendientes de integración; no se simula su funcionamiento.</p></section></q-page></template>
